import sys
from math import gcd

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    forbidden = set()
    if n > 0:
        for _ in range(n):
            forbidden.add(int(next(iterator)))

    if m == 1:
        print(0)
        print()
        return

    current = 1
    visited = set()
    sequence = []

    if 0 in forbidden:
        pass
    else:
        if 0 not in visited:
            visited.add(0)
            sequence.append(0)
            current = 0

    while True:
        if current in forbidden:
            break
        if current in visited:
            break

        visited.add(current)

        found_next = False
        best_val = -1

        if current == 0:
            break

        for val in range(m):
            if val == 0:
                continue

            next_prod = (current * val) % m

            if next_prod not in forbidden and next_prod not in visited:
                best_val = val
                found_next = True
                break

        if not found_next:
            break

        sequence.append(best_val)
        current = (current * best_val) % m

    print(len(sequence))
    print(*(sequence))

if __name__ == "__main__":
    solve()
